// Sunlit wildflower meadow with winding path
// All rendering via Canvas 2D direct drawing

// ---------- helpers ----------
function lerp(a,b,t){return a+(b-a)*t;}
function clamp(v,a,b){return v<a?a:v>b?b:v;}
function smooth(t){return t*t*(3-2*t);}

// value noise
const NG = 256;
const noiseGrid = new Float32Array(NG*NG);
for(let i=0;i<NG*NG;i++) noiseGrid[i]=Math.random();
function noise2(x,y){
  const xi=Math.floor(x), yi=Math.floor(y);
  const xf=x-xi, yf=y-yi;
  const x0=((xi%NG)+NG)%NG, y0=((yi%NG)+NG)%NG;
  const x1=(x0+1)%NG, y1=(y0+1)%NG;
  const s=smooth(xf), t=smooth(yf);
  const a=noiseGrid[y0*NG+x0], b=noiseGrid[y0*NG+x1];
  const c=noiseGrid[y1*NG+x0], d=noiseGrid[y1*NG+x1];
  return lerp(lerp(a,b,s), lerp(c,d,s), t);
}
function fbm(x,y,oct){
  let v=0,amp=0.5,f=1;
  for(let i=0;i<oct;i++){ v+=amp*noise2(x*f,y*f); f*=2; amp*=0.5; }
  return v;
}

// horizon
const horizonY = H*0.52;
const sunX = W*0.83, sunY = H*0.22;

// ---------- SKY ----------
function drawSky(){
  const g=ctx.createLinearGradient(0,0,0,horizonY+40);
  g.addColorStop(0, '#7ba7cf');
  g.addColorStop(0.35,'#a8c6de');
  g.addColorStop(0.7, '#cfdde8');
  g.addColorStop(1, '#ecdfc6');
  ctx.fillStyle=g;
  ctx.fillRect(0,0,W,horizonY+40);
  // subtle warm glow around sun
  const rg=ctx.createRadialGradient(sunX,sunY,10,sunX,sunY,W*0.5);
  rg.addColorStop(0,'rgba(255,244,214,0.55)');
  rg.addColorStop(0.3,'rgba(255,238,205,0.18)');
  rg.addColorStop(1,'rgba(255,238,205,0)');
  ctx.fillStyle=rg;
  ctx.fillRect(0,0,W,horizonY+40);
}

// layered broad clouds using many soft strokes
function drawClouds(){
  // use a low-res offscreen mask to define cloud masses, then paint soft strokes on main
  const cw = 240, ch=160;
  const mask = createCanvas(cw,ch);
  const mx = mask.getContext('2d');
  const md = mx.createImageData(cw,ch);
  for(let y=0;y<ch;y++){
    const ny=y/ch;
    for(let x=0;x<cw;x++){
      const nx=x/cw;
      let v = fbm(nx*3.2+1.2, ny*2.6+5.7, 4);
      v += 0.35*fbm(nx*6.5+9.1, ny*4.2+2.3, 3);
      // horizontal banding emphasis
      v *= 0.9 + 0.15*Math.sin(nx*4.2+ny*1.7);
      // fade near horizon
      const fade = smooth(clamp(ny*1.4,0,1));
      v *= fade;
      v = clamp((v-0.35)*1.9, 0, 1);
      const a = clamp(v,0,1);
      const idx=(y*cw+x)*4;
      md.data[idx]=255; md.data[idx+1]=255; md.data[idx+2]=250;
      md.data[idx+3]=a*230;
    }
  }
  mx.putImageData(md,0,0);

  ctx.save();
  ctx.globalAlpha=0.85;
  ctx.drawImage(mask,0,0,W,horizonY+10);
  ctx.restore();

  // bright rims and soft shadow undersides as clustered strokes
  ctx.save();
  for(let iter=0;iter<400;iter++){
    const x=Math.random()*W;
    const y0=Math.random()*horizonY*0.85;
    const a=fbm(x*0.007,y0*0.011,3);
    if(a<0.5) continue;
    const len=40+Math.random()*120;
    const curve=(Math.random()-0.5)*30;
    // brightness influenced by proximity to sun
    const dx=x-sunX, dy=y0-sunY;
    const dist=Math.sqrt(dx*dx+dy*dy);
    const sunFactor=clamp(1-dist/700,0,1);
    const isShadow=Math.random()<0.4;
    ctx.beginPath();
    ctx.moveTo(x,y0);
    ctx.quadraticCurveTo(x+len*0.5,y0+curve, x+len, y0+curve*0.4);
    if(isShadow){
      ctx.strokeStyle=`rgba(150,160,180,${0.06+0.05*Math.random()})`;
    } else {
      const wr=245+sunFactor*10;
      ctx.strokeStyle=`rgba(${wr|0},${(wr-4)|0},${(wr-20)|0},${0.10+0.10*sunFactor})`;
    }
    ctx.lineWidth=6+Math.random()*18;
    ctx.lineCap='round';
    ctx.stroke();
  }
  ctx.restore();
}

// ---------- DISTANT HILLS ----------
function drawHills(){
  // three layers, muted atmospheric greens
  function hillLayer(baseY, amp, freq, phase, colTop, colBot, detail){
    ctx.beginPath();
    ctx.moveTo(0,H);
    for(let x=0;x<=W;x+=4){
      const nx=x/W;
      const y = baseY - Math.sin(nx*freq+phase)*amp
                    - Math.sin(nx*freq*2.3+phase*1.7)*amp*0.35
                    - Math.sin(nx*freq*0.6+phase*2.1)*amp*0.5;
      ctx.lineTo(x,y);
    }
    ctx.lineTo(W,H);
    ctx.closePath();
    const g=ctx.createLinearGradient(0,baseY-amp*2,0,baseY+amp*3);
    g.addColorStop(0,colTop);
    g.addColorStop(1,colBot);
    ctx.fillStyle=g;
    ctx.fill();
    // texture along the ridgeline
    for(let i=0;i<detail;i++){
      const x=Math.random()*W;
      const nx=x/W;
      const y = baseY - Math.sin(nx*freq+phase)*amp
                    - Math.sin(nx*freq*2.3+phase*1.7)*amp*0.35
                    - Math.sin(nx*freq*0.6+phase*2.1)*amp*0.5;
      const yy=y+Math.random()*40-5;
      if(yy>baseY+60) continue;
      const shade=0.3+Math.random()*0.4;
      ctx.fillStyle = Math.random()<0.5
        ? `rgba(90,110,80,${0.10*shade})`
        : `rgba(160,180,140,${0.10*shade})`;
      ctx.fillRect(x,yy,1+Math.random()*2,1+Math.random()*2);
    }
  }
  // farthest
  hillLayer(horizonY-18, 22, 3.1, 0.8, '#a9b8a4', '#94a488', 600);
  // mid hills
  hillLayer(horizonY+8, 30, 2.4, 2.3, '#8fa578', '#7d9366', 1200);
  // near-hill band
  hillLayer(horizonY+55, 42, 1.9, 4.1, '#7a9459', '#5f7a45', 1800);
}

// ---------- PATCHWORK MIDGROUND MEADOW ----------
function drawMidMeadow(){
  const topY = horizonY+55;
  const botY = H*0.72;
  // base gradient
  const g=ctx.createLinearGradient(0,topY,0,botY);
  g.addColorStop(0,'#6c8a4a');
  g.addColorStop(0.5,'#7ea04f');
  g.addColorStop(1,'#8eae55');
  ctx.fillStyle=g;
  ctx.fillRect(0,topY,W,botY-topY);

  // large correlated color patches
  for(let i=0;i<220;i++){
    const x=Math.random()*W;
    const y=topY+Math.random()*(botY-topY);
    const n=fbm(x*0.004,y*0.006,3);
    if(n<0.45) continue;
    const rr=40+Math.random()*120;
    const warm=Math.random()<0.55;
    const g2=ctx.createRadialGradient(x,y,0,x,y,rr);
    if(warm) g2.addColorStop(0,'rgba(190,205,110,0.18)');
    else g2.addColorStop(0,'rgba(70,110,60,0.20)');
    g2.addColorStop(1,'rgba(0,0,0,0)');
    ctx.fillStyle=g2;
    ctx.beginPath();
    ctx.ellipse(x,y,rr,rr*0.6,0,0,Math.PI*2);
    ctx.fill();
  }

  // small flower flecks
  for(let i=0;i<4200;i++){
    const x=Math.random()*W;
    const y=topY+Math.random()*(botY-topY);
    const depth=(y-topY)/(botY-topY);
    const n=fbm(x*0.01,y*0.014,2);
    if(n<0.52) continue;
    if(Math.random()<0.55){
      // white daisy fleck
      ctx.fillStyle=`rgba(248,246,232,${0.55+0.4*Math.random()})`;
      ctx.fillRect(x,y,1.5+depth*1.2,1);
    } else if(Math.random()<0.55){
      // yellow buttercup
      ctx.fillStyle=`rgba(240,205,70,${0.55+0.4*Math.random()})`;
      ctx.fillRect(x,y,1.4+depth,1);
    } else {
      // violet
      ctx.fillStyle=`rgba(150,120,190,${0.5+0.35*Math.random()})`;
      ctx.fillRect(x,y,1.2,1);
    }
  }

  // grass texture on midground
  for(let i=0;i<9000;i++){
    const x=Math.random()*W;
    const y=topY+Math.random()*(botY-topY);
    const depth=(y-topY)/(botY-topY);
    const n=fbm(x*0.008,y*0.01,2);
    if(n<0.4) continue;
    const len=2+depth*7;
    const lean=(Math.random()-0.5)*2;
    const bright = Math.random()<0.5;
    ctx.strokeStyle = bright
      ? `rgba(180,205,${120+depth*30|0},${0.25+0.3*Math.random()})`
      : `rgba(70,100,50,${0.2+0.3*Math.random()})`;
    ctx.lineWidth=0.8;
    ctx.beginPath();
    ctx.moveTo(x,y);
    ctx.lineTo(x+lean*len*0.5, y-len);
    ctx.stroke();
  }
}

// ---------- PATH ----------
// path curve: from lower right to left-third horizon
const pathPts = [
  {x:W*0.72, y:H*1.0},
  {x:W*0.60, y:H*0.85},
  {x:W*0.52, y:H*0.73},
  {x:W*0.44, y:H*0.63},
  {x:W*0.38, y:horizonY+55}
];

function pathPointAt(t){
  // simple piecewise cubic-ish through control pts using de casteljau on 2 segs
  // use 3-segment quadratic blend
  const p0=pathPts[0],p1=pathPts[1],p2=pathPts[2],p3=pathPts[3],p4=pathPts[4];
  if(t<0.5){
    const s=t/0.5;
    const a={x:lerp(p0.x,p1.x,s),y:lerp(p0.y,p1.y,s)};
    const b={x:lerp(p1.x,p2.x,s),y:lerp(p1.y,p2.y,s)};
    return {x:lerp(a.x,b.x,s),y:lerp(a.y,b.y,s)};
  } else {
    const s=(t-0.5)/0.5;
    const a={x:lerp(p2.x,p3.x,s),y:lerp(p2.y,p3.y,s)};
    const b={x:lerp(p3.x,p4.x,s),y:lerp(p3.y,p4.y,s)};
    return {x:lerp(a.x,b.x,s),y:lerp(a.y,b.y,s)};
  }
}

function drawPath(){
  // widen near bottom, narrow near top
  const segs=160;
  const left=[], right=[];
  for(let i=0;i<=segs;i++){
    const t=i/segs;
    const p=pathPointAt(t);
    const w = lerp(W*0.055, W*0.004, Math.pow(t,0.7));
    // tangent
    const p2=pathPointAt(Math.min(1,t+0.001));
    const dx=p2.x-p.x, dy=p2.y-p.y;
    const len=Math.sqrt(dx*dx+dy*dy)||1;
    const nx=-dy/len, ny=dx/len;
    left.push({x:p.x+nx*w,y:p.y+ny*w});
    right.push({x:p.x-nx*w,y:p.y-ny*w});
  }
  // earth body
  ctx.beginPath();
  ctx.moveTo(left[0].x,left[0].y);
  for(let i=1;i<left.length;i++) ctx.lineTo(left[i].x,left[i].y);
  for(let i=right.length-1;i>=0;i--) ctx.lineTo(right[i].x,right[i].y);
  ctx.closePath();
  // soft blurred edge — draw wide faint stroke first
  ctx.save();
  ctx.lineJoin='round';
  const pg=ctx.createLinearGradient(0,H*0.6,0,H);
  pg.addColorStop(0,'#9a8768');
  pg.addColorStop(0.5,'#b9a483');
  pg.addColorStop(1,'#c8b48f');
  ctx.fillStyle=pg;
  ctx.fill();
  ctx.restore();

  // path texture strokes — small warm earth tones
  ctx.save();
  ctx.beginPath();
  ctx.moveTo(left[0].x,left[0].y);
  for(let i=1;i<left.length;i++) ctx.lineTo(left[i].x,left[i].y);
  for(let i=right.length-1;i>=0;i--) ctx.lineTo(right[i].x,right[i].y);
  ctx.closePath();
  ctx.clip();
  for(let i=0;i<6000;i++){
    const t=Math.random();
    const p=pathPointAt(t);
    const w=lerp(W*0.055,W*0.004,Math.pow(t,0.7));
    const off=(Math.random()-0.5)*2*w;
    const x=p.x+off, y=p.y+(Math.random()-0.5)*10;
    const shade=Math.random();
    let col;
    if(shade<0.3) col='rgba(140,118,88,0.5)';
    else if(shade<0.65) col='rgba(180,160,125,0.5)';
    else col='rgba(210,190,150,0.55)';
    ctx.fillStyle=col;
    ctx.fillRect(x,y,1+Math.random()*2.5,1+Math.random()*1.5);
  }
  // small stones
  for(let i=0;i<140;i++){
    const t=Math.random();
    const p=pathPointAt(t);
    const w=lerp(W*0.055,W*0.004,Math.pow(t,0.7));
    const x=p.x+(Math.random()-0.5)*2*w*0.9;
    const y=p.y+(Math.random()-0.5)*6;
    const r=1+Math.random()*(2-t*1.5);
    const g2=ctx.createRadialGradient(x,y-r*0.3,0,x,y,r);
    g2.addColorStop(0,'#d8c8a8');
    g2.addColorStop(1,'#8a7458');
    ctx.fillStyle=g2;
    ctx.beginPath();
    ctx.ellipse(x,y,r,r*0.7,Math.random()*Math.PI,0,Math.PI*2);
    ctx.fill();
  }
  ctx.restore();
}

// ---------- FOREGROUND GRASS ----------
function drawGrassStalk(x,y,h,lean,lean2,shade,bright){
  ctx.beginPath();
  const w = Math.max(0.8, h*0.05);
  ctx.moveTo(x, y);
  ctx.quadraticCurveTo(x+lean*0.5, y-h*0.55, x+lean, y-h);
  ctx.lineWidth = w;
  ctx.strokeStyle = shade;
  ctx.lineCap='round';
  ctx.stroke();
  if(bright){
    // highlight on lit side (sun is from right)
    ctx.beginPath();
    ctx.moveTo(x+0.4, y);
    ctx.quadraticCurveTo(x+lean*0.5+0.3, y-h*0.55, x+lean+0.3, y-h);
    ctx.lineWidth = Math.max(0.5, w*0.4);
    ctx.strokeStyle = bright;
    ctx.stroke();
  }
}

function drawForegroundGrass(){
  // clustered dense grass in foreground, bottom ~40% of canvas
  // Several clumps with varying density
  const grassZones=[
    {x:W*0.08,y:H*0.96,count:180,scale:1.3},
    {x:W*0.20,y:H*0.98,count:200,scale:1.4},
    {x:W*0.32,y:H*0.94,count:160,scale:1.2},
    {x:W*0.46,y:H*1.0,count:220,scale:1.4},
    {x:W*0.58,y:H*0.96,count:140,scale:1.1},
    {x:W*0.85,y:H*0.98,count:240,scale:1.5},
    {x:W*0.92,y:H*0.93,count:150,scale:1.2},
    {x:W*0.75,y:H*0.90,count:130,scale:1.0} // near path
  ];
  for(const z of grassZones){
    for(let i=0;i<z.count;i++){
      const ang=Math.random()*Math.PI*2;
      const rad=Math.random()*120;
      const x=z.x+Math.cos(ang)*rad;
      const y=z.y+Math.sin(ang)*rad*0.35;
      if(y<H*0.55) continue;
      const h=(20+Math.random()*80)*z.scale;
      const lean=(Math.random()-0.5)*h*0.7 + 4; // slight sun lean
      const g=fbm(x*0.01,y*0.01,2);
      let shade, bright;
      if(Math.random()<0.4){
        shade=`rgba(${40+g*30|0},${65+g*30|0},${25+g*20|0},0.85)`;
      } else if(Math.random()<0.5){
        shade=`rgba(${80+g*40|0},${110+g*35|0},${45+g*25|0},0.88)`;
      } else {
        shade=`rgba(${55+g*35|0},${85+g*30|0},${35+g*22|0},0.85)`;
      }
      if(Math.random()<0.4 && x > W*0.4){
        bright=`rgba(${200+g*40|0},${220+g*25|0},${120+g*30|0},0.65)`;
      } else bright=null;
      drawGrassStalk(x,y,h,lean,(Math.random()-0.5)*8,shade,bright);
    }
  }
  // extra tall blades in extreme foreground
  for(let i=0;i<90;i++){
    const x=Math.random()*W;
    const y=H*0.97+Math.random()*20;
    const h=80+Math.random()*140;
    const lean=(Math.random()-0.5)*90+8;
    const g=Math.random();
    let shade=`rgba(${50+g*40|0},${85+g*40|0},${30+g*25|0},0.9)`;
    const bright = x>W*0.4
      ? `rgba(${215+g*30|0},${225+g*20|0},${130+g*40|0},0.7)`
      : null;
    drawGrassStalk(x,y,h,lean,(Math.random()-0.5)*12,shade,bright);
  }
}

// ---------- FLOWERS ----------
function drawDaisy(x,y,scale,rot,lightBoost){
  // stem
  const stemH=60*scale;
  const stemLean=(Math.random()-0.5)*30*scale + 3;
  ctx.beginPath();
  ctx.moveTo(x,y);
  ctx.quadraticCurveTo(x+stemLean*0.4,y-stemH*0.5, x+stemLean, y-stemH);
  ctx.lineWidth=Math.max(1.2, 2.2*scale);
  ctx.strokeStyle=`rgba(${60+Math.random()*30|0},${95+Math.random()*30|0},${40+Math.random()*20|0},0.95)`;
  ctx.lineCap='round';
  ctx.stroke();
  const cx=x+stemLean, cy=y-stemH;

  // petals
  const petalCount=10+Math.floor(Math.random()*5);
  const R=11*scale;
  ctx.save();
  ctx.translate(cx,cy);
  ctx.rotate(rot);
  for(let i=0;i<petalCount;i++){
    const a=(i/petalCount)*Math.PI*2 + (Math.random()-0.5)*0.15;
    const plen=R*(0.85+Math.random()*0.3);
    const pw=R*0.28*(0.85+Math.random()*0.3);
    ctx.save();
    ctx.rotate(a);
    const g=ctx.createLinearGradient(0,0,R,0);
    const b=lightBoost?(245+Math.random()*10):(240+Math.random()*10);
    g.addColorStop(0,`rgba(${b|0},${(b-4)|0},${(b-18)|0},1)`);
    g.addColorStop(1,`rgba(${(b-25)|0},${(b-22)|0},${(b-35)|0},1)`);
    ctx.fillStyle=g;
    // irregular petal via bezier
    ctx.beginPath();
    ctx.moveTo(0,-pw*0.5);
    ctx.bezierCurveTo(plen*0.3, -pw*0.9, plen*0.85, -pw*0.5, plen, (Math.random()-0.5)*pw*0.3);
    ctx.bezierCurveTo(plen*0.85, pw*0.6, plen*0.3, pw*0.9, 0, pw*0.5);
    ctx.bezierCurveTo(plen*0.15, pw*0.2, plen*0.15, -pw*0.2, 0, -pw*0.5);
    ctx.fill();
    ctx.restore();
  }
  // center
  const cg=ctx.createRadialGradient(0,-1,0,0,0,R*0.4);
  cg.addColorStop(0,'#f7d84a');
  cg.addColorStop(0.6,'#e0b830');
  cg.addColorStop(1,'#a8871c');
  ctx.fillStyle=cg;
  ctx.beginPath();
  ctx.arc(0,0,R*0.4,0,Math.PI*2);
  ctx.fill();
  // tiny dots on center
  for(let i=0;i<20;i++){
    const a=Math.random()*Math.PI*2;
    const r=Math.random()*R*0.35;
    ctx.fillStyle=`rgba(${160+Math.random()*40|0},${120+Math.random()*40|0},${30+Math.random()*30|0},0.5)`;
    ctx.fillRect(Math.cos(a)*r, Math.sin(a)*r, 1, 1);
  }
  ctx.restore();
}

function drawButtercup(x,y,scale,rot,lightBoost){
  const stemH=55*scale;
  const stemLean=(Math.random()-0.5)*25*scale + 2;
  ctx.beginPath();
  ctx.moveTo(x,y);
  ctx.quadraticCurveTo(x+stemLean*0.4,y-stemH*0.5, x+stemLean, y-stemH);
  ctx.lineWidth=Math.max(1, 1.8*scale);
  ctx.strokeStyle=`rgba(${50+Math.random()*30|0},${85+Math.random()*30|0},${35+Math.random()*20|0},0.9)`;
  ctx.stroke();

  const cx=x+stemLean, cy=y-stemH;
  const R=7*scale;
  ctx.save();
  ctx.translate(cx,cy);
  ctx.rotate(rot);
  const petalCount=5;
  for(let i=0;i<petalCount;i++){
    const a=(i/petalCount)*Math.PI*2 + Math.random()*0.1;
    ctx.save();
    ctx.rotate(a);
    const g=ctx.createRadialGradient(R*0.5,0,1,R*0.5,0,R);
    g.addColorStop(0, lightBoost?'#fff0a0':'#ffe680');
    g.addColorStop(0.6,'#ffd233');
    g.addColorStop(1,'#d9a820');
    ctx.fillStyle=g;
    ctx.beginPath();
    ctx.ellipse(R*0.55,0,R*0.6,R*0.55,0,0,Math.PI*2);
    ctx.fill();
    ctx.restore();
  }
  // glossy center
  const cg=ctx.createRadialGradient(-1,-1,0,0,0,R*0.3);
  cg.addColorStop(0,'#fff8c0');
  cg.addColorStop(1,'#d4a018');
  ctx.fillStyle=cg;
  ctx.beginPath();
  ctx.arc(0,0,R*0.28,0,Math.PI*2);
  ctx.fill();
  ctx.restore();
}

function drawViolet(x,y,scale,rot){
  const stemH=45*scale;
  const stemLean=(Math.random()-0.5)*22*scale;
  ctx.beginPath();
  ctx.moveTo(x,y);
  ctx.quadraticCurveTo(x+stemLean*0.4,y-stemH*0.5, x+stemLean, y-stemH);
  ctx.lineWidth=Math.max(1, 1.4*scale);
  ctx.strokeStyle='rgba(70,110,45,0.9)';
  ctx.stroke();
  const cx=x+stemLean, cy=y-stemH;
  const R=5*scale;
  ctx.save();
  ctx.translate(cx,cy);
  ctx.rotate(rot);
  const petalCount=4+Math.floor(Math.random()*2);
  for(let i=0;i<petalCount;i++){
    const a=(i/petalCount)*Math.PI*2;
    ctx.save();
    ctx.rotate(a);
    const g=ctx.createRadialGradient(R*0.5,0,1,R*0.5,0,R);
    g.addColorStop(0,'#b79cdd');
    g.addColorStop(1,'#7a5aa5');
    ctx.fillStyle=g;
    ctx.beginPath();
    ctx.ellipse(R*0.5,0,R*0.55,R*0.45,0,0,Math.PI*2);
    ctx.fill();
    ctx.restore();
  }
  // center with tiny yellow dot
  ctx.fillStyle='#f5e070';
  ctx.beginPath();
  ctx.arc(0,0,R*0.22,0,Math.PI*2);
  ctx.fill();
  ctx.fillStyle='#4a3070';
  ctx.beginPath();
  ctx.arc(0,0,R*0.1,0,Math.PI*2);
  ctx.fill();
  ctx.restore();
}

function drawFlowerClusters(){
  // clustered flower distribution — not uniform
  const clusters=[
    {x:W*0.10,y:H*0.82,r:90,n:5,type:'mix'},
    {x:W*0.22,y:H*0.88,r:110,n:6,type:'daisy'},
    {x:W*0.30,y:H*0.79,r:80,n:4,type:'butter'},
    {x:W*0.48,y:H*0.86,r:90,n:5,type:'mix'},
    {x:W*0.88,y:H*0.85,r:120,n:7,type:'mix'},
    {x:W*0.92,y:H*0.72,r:70,n:3,type:'daisy'},
    {x:W*0.66,y:H*0.80,r:85,n:4,type:'butter'},
    {x:W*0.40,y:H*0.92,r:100,n:5,type:'mix'},
    {x:W*0.78,y:H*0.78,r:75,n:3,type:'violet'},
    {x:W*0.16,y:H*0.72,r:60,n:3,type:'daisy'},
    {x:W*0.60,y:H*0.94,r:110,n:5,type:'mix'}
  ];
  for(const c of clusters){
    for(let i=0;i<c.n;i++){
      const a=Math.random()*Math.PI*2;
      const rad=Math.random()*c.r;
      const x=c.x+Math.cos(a)*rad;
      const y=c.y+Math.sin(a)*rad*0.5;
      if(y<H*0.6||y>H*1.02) continue;
      // avoid sitting right on path
      const pathP=findNearestPath(x,y);
      if(pathP.dist<30) continue;
      const scale=lerp(0.7,1.15, (y-H*0.6)/(H*0.4)) * (0.85+Math.random()*0.3);
      const rot=Math.random()*Math.PI*2;
      const lit = x>W*0.45;
      let type=c.type;
      if(type==='mix'){
        const r=Math.random();
        type= r<0.5?'daisy': r<0.85?'butter':'violet';
      }
      if(type==='daisy') drawDaisy(x,y,scale,rot,lit);
      else if(type==='butter') drawButtercup(x,y,scale,rot,lit);
      else drawViolet(x,y,scale,rot);
    }
  }
  // a few scattered singles
  for(let i=0;i<14;i++){
    const x=Math.random()*W;
    const y=H*0.72+Math.random()*H*0.28;
    const pp=findNearestPath(x,y);
    if(pp.dist<40) continue;
    const scale=0.6+Math.random()*0.4;
    const rot=Math.random()*Math.PI*2;
    const lit=x>W*0.5;
    const t=Math.random();
    if(t<0.45) drawDaisy(x,y,scale,rot,lit);
    else if(t<0.8) drawButtercup(x,y,scale,rot,lit);
    else drawViolet(x,y,scale,rot);
  }
}

function findNearestPath(x,y){
  let best=1e9;
  for(let i=0;i<=40;i++){
    const p=pathPointAt(i/40);
    const d=Math.sqrt((p.x-x)*(p.x-x)+(p.y-y)*(p.y-y));
    if(d<best) best=d;
  }
  return {dist:best};
}

// ---------- ATMOSPHERIC LIGHT / SUN GLOW ----------
function drawSunGlow(){
  ctx.save();
  ctx.globalCompositeOperation='screen';
  const g=ctx.createRadialGradient(sunX,sunY,10,sunX,sunY,W*0.55);
  g.addColorStop(0,'rgba(255,246,215,0.55)');
  g.addColorStop(0.15,'rgba(255,240,200,0.28)');
  g.addColorStop(0.5,'rgba(255,235,195,0.10)');
  g.addColorStop(1,'rgba(255,235,195,0)');
  ctx.fillStyle=g;
  ctx.fillRect(0,0,W,H);
  ctx.restore();
}

// soft clouds nearest horizon
function drawHorizonHaze(){
  ctx.save();
  const g=ctx.createLinearGradient(0,horizonY-60,0,horizonY+100);
  g.addColorStop(0,'rgba(230,225,210,0)');
  g.addColorStop(0.5,'rgba(230,220,200,0.35)');
  g.addColorStop(1,'rgba(220,210,190,0)');
  ctx.fillStyle=g;
  ctx.fillRect(0,horizonY-60,W,160);
  ctx.restore();
}

// gentle vignette
function drawVignette(){
  ctx.save();
  const g=ctx.createRadialGradient(W*0.5,H*0.42,H*0.4,W*0.5,H*0.5,W*0.85);
  g.addColorStop(0,'rgba(0,0,0,0)');
  g.addColorStop(1,'rgba(20,30,15,0.28)');
  ctx.fillStyle=g;
  ctx.fillRect(0,0,W,H);
  ctx.restore();
}

